pub type Rect = {
  x: Float64;
  y: Float64;
  width: Float64;
  height: Float64;
}

fn area(r: &Rect) -> Float64 {
  return r.width * r.height;
}

fn shift(r: &mut Rect, dx: Float64, dy: Float64) -> Unit {
  r.x = r.x + dx;
  r.y = r.y + dy;
}

fn main() -> Int {
  var r = Rect{ x: 0.0, y: 0.0, width: 5.0, height: 3.0 };
  shift(&mut r, 2.0, 1.0);
  let a = area(&r);
  return a as Int;
}
